#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n;scanf("%d",&n);vector<long long>st;
for(int i=0;i<n;++i){long long x;scanf("%lld",&x);bool alive=true;
while(alive&&x<0&&!st.empty()&&st.back()>0){
if(st.back()<-x)st.pop_back();
else if(st.back()==-x){st.pop_back();alive=false;}
else alive=false;}
if(alive)st.push_back(x);}
for(size_t i=0;i<st.size();++i){if(i)printf(" ");printf("%lld",st[i]);}
printf("\n");return 0;}

